import VueApexCharts from 'vue3-apexcharts';
export default {
  components: {
    apexchart: VueApexCharts
  },
  props: {
    bardata: Array,
    chartId: String
  },
  data() {
    // Sample raw data
    const rawData = this.bardata;

    // Transform the raw data into series format
    const seriesData = rawData.map(item => ({
      name: item.label,
      data: item.y.map((value, index) => ({
        x: item.x[index],
        y: parseInt(value, 10) // Convert string to number
      }))
    }));
    return {
      series: seriesData,
      chartOptions: {
        chart: {
          type: "bar",
          height: 430,
          toolbar: {
            show: false // Hide the toolbar including the download button
          }
        },
        plotOptions: {
          bar: {
            horizontal: true,
            dataLabels: {
              position: "top"
            }
          }
        },
        dataLabels: {
          enabled: true,
          offsetX: -6,
          style: {
            fontSize: "12px",
            colors: ["#fff"]
          }
        },
        stroke: {
          show: true,
          width: 1,
          colors: ["#fff"]
        },
        tooltip: {
          shared: true,
          intersect: false
        },
        xaxis: {
          categories: rawData[0].x // Assuming x values are the same for all data entries
        }
      }
    };
  }
};
